"""A trained content classifier that reads pages and predicts injection.

This is the defense most teams reach for first: look at the untrusted content,
decide whether it is hostile, refuse if so. It is implemented here as a real
TF-IDF + logistic-regression model trained on a labeled corpus, not as a
keyword list, because a keyword list would fail for uninteresting reasons and
would say nothing about whether *content filtering* works.

Deliberately, the classifier is given every advantage:

* it trains on payloads generated by the very attack objects it is scored
  against, so the fixed attack suite is in-distribution;
* the benign catalog pages are in its clean training data too, so it has no
  excuse for over-blocking honest listings;
* it sees the whole page, assembled by the same
  :meth:`~lure.environment.models.Page.as_text` used at inference.

Read its headline numbers with that in mind. Strong held-out precision and
recall here describe performance on injections drawn from the distribution it
was trained on, which is exactly the condition the LLM red-team tier is built
to break. The number worth quoting is not this one; it is what survives novel
phrasing.

Training happens once per process and is cached, taking milliseconds on a
corpus this size. Every seed is pinned, so the model, the split, and the
reported metrics are identical on every run and every machine.
"""

from __future__ import annotations

from dataclasses import dataclass
from functools import lru_cache

from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.linear_model import LogisticRegression
from sklearn.metrics import precision_score, recall_score
from sklearn.model_selection import train_test_split
from sklearn.pipeline import FeatureUnion, Pipeline

from lure.defenses.base import Defense
from lure.defenses.training_data import LABEL_INJECTED, build_corpus
from lure.environment.marketplace import Marketplace
from lure.environment.models import Cart, IntentMandate, PaymentMandate

__all__ = ["ContentClassifierDefense", "TrainedClassifier", "train_classifier"]

#: Pinned so the split, the solver and the fitted coefficients are reproducible.
RANDOM_STATE = 0

#: Held-out fraction. Large enough for the reported metrics to mean something
#: on a corpus this size, small enough to leave the model well fit.
TEST_SIZE = 0.25


@dataclass(frozen=True)
class TrainedClassifier:
    """A fitted pipeline plus the held-out scores it earned.

    Attributes:
        pipeline: Fitted TF-IDF + logistic-regression pipeline.
        precision: Held-out precision for the injected class. Low precision
            means over-blocking honest listings.
        recall: Held-out recall for the injected class. Low recall means
            injections get through.
        n_train: Training sample count.
        n_test: Held-out sample count.
    """

    pipeline: Pipeline
    precision: float
    recall: float
    n_train: int
    n_test: int


def _build_features() -> FeatureUnion:
    """Return the feature extractor: word n-grams plus character n-grams.

    Two views, because an injected payload is a short appendix to a much
    longer clean listing and word-level TF-IDF alone dilutes it:

    * **Word 1-2 grams** capture the phrasing of an override request
      ("minimum order", "pricing correction", "ship this order"), which is
      what has any chance of generalising to wording the model has not seen.
    * **Character 3-5 grams** capture the sub-token shapes that survive
      rephrasing -- ``[[INSTRUCTION]]``, ``acct:``, ``addr:``, ``set_payee`` --
      and are what let it catch the structured register reliably.

    Note the asymmetry, since it is the finding rather than an implementation
    detail: the character view is doing most of the work, and it is precisely
    the view that generalises least. A payload with no structured token and no
    familiar account prefix has to be caught on phrasing alone.
    """
    return FeatureUnion(
        [
            (
                "word",
                TfidfVectorizer(
                    lowercase=True,
                    ngram_range=(1, 2),
                    sublinear_tf=True,
                    min_df=1,
                ),
            ),
            (
                "char",
                TfidfVectorizer(
                    analyzer="char_wb",
                    ngram_range=(3, 5),
                    sublinear_tf=True,
                    min_df=1,
                ),
            ),
        ]
    )


def train_classifier(marketplace: Marketplace | None = None) -> TrainedClassifier:
    """Train on a catalog's corpus and score on a deterministic held-out split.

    Stratified so both classes appear in the held-out set regardless of corpus
    balance; ``liblinear`` because it is deterministic on data this size.

    Args:
        marketplace: Catalog whose pages and attacks seed the corpus. Defaults
            to the small catalog. A classifier scored on the scaled catalog is
            trained on the scaled catalog, so it keeps the same in-distribution
            advantage there that it has on the small one.
    """
    corpus = build_corpus(marketplace)

    texts_train, texts_test, labels_train, labels_test = train_test_split(
        corpus.texts,
        corpus.labels,
        test_size=TEST_SIZE,
        random_state=RANDOM_STATE,
        stratify=corpus.labels,
    )

    pipeline = Pipeline(
        [
            ("features", _build_features()),
            (
                "clf",
                LogisticRegression(
                    random_state=RANDOM_STATE,
                    solver="liblinear",
                    C=8.0,
                    class_weight="balanced",
                    max_iter=1000,
                ),
            ),
        ]
    )
    pipeline.fit(texts_train, labels_train)

    predicted = pipeline.predict(texts_test)
    return TrainedClassifier(
        pipeline=pipeline,
        precision=float(
            precision_score(labels_test, predicted, pos_label=LABEL_INJECTED, zero_division=0)
        ),
        recall=float(
            recall_score(labels_test, predicted, pos_label=LABEL_INJECTED, zero_division=0)
        ),
        n_train=len(texts_train),
        n_test=len(texts_test),
    )


@lru_cache(maxsize=8)
def _cached_classifier(catalog_name: str) -> TrainedClassifier:
    """Return the process-wide trained model for one catalog, training on first use.

    Keyed by catalog name rather than by marketplace object so that every
    fresh copy of the same catalog shares one model.
    """
    from lure.environment.catalog import build_marketplace

    return train_classifier(build_marketplace(catalog_name))


class ContentClassifierDefense(Defense):
    """Block a transaction when the pages behind its cart look injected."""

    name = "ContentClassifierDefense"

    def __init__(
        self,
        model: TrainedClassifier | None = None,
        marketplace: Marketplace | None = None,
    ) -> None:
        """Initialise with a trained model, training one if none is given.

        Args:
            model: Pre-trained model to reuse.
            marketplace: Catalog to train for when ``model`` is not given.
                Defaults to the small catalog. Trained models are cached per
                catalog, so constructing the defense repeatedly costs nothing.
        """
        if model is None:
            model = _cached_classifier(marketplace.name if marketplace else "small")
        self.model = model

    @property
    def precision(self) -> float:
        """Return held-out precision for the injected class."""
        return self.model.precision

    @property
    def recall(self) -> float:
        """Return held-out recall for the injected class."""
        return self.model.recall

    def validate(
        self,
        payment: PaymentMandate,
        cart: Cart,
        intent: IntentMandate,
        marketplace: Marketplace,
        ship_to: str | None = None,
    ) -> tuple[bool, str]:
        """Classify the content behind the cart and block if it predicts injection.

        Note what this defense does *not* look at: the amount, the payee, the
        quantities, the delivery address. It reasons entirely about text. That
        is the whole thesis of a content filter, and the reason its failures
        are invisible to it -- an injection it does not recognise produces no
        signal at all.
        """
        text = self._cart_page_text(cart, marketplace)
        if not text.strip():
            return True, ""

        predicted = self.model.pipeline.predict([text])[0]
        if predicted == LABEL_INJECTED:
            return False, (
                "content classifier flagged injected instructions on a product "
                "page backing this cart"
            )
        return True, ""

    def _cart_page_text(self, cart: Cart, marketplace: Marketplace) -> str:
        """Return the combined page text for every product in the cart.

        Products with no page contribute nothing rather than raising: a missing
        page is not evidence of an attack.
        """
        chunks: list[str] = []
        for item in cart.items:
            try:
                page = marketplace.get_page(item.product.id)
            except KeyError:
                continue
            chunks.append(page.as_text())
        return "\n".join(chunks)
